import (
	"slices"
	"testing"
)

// TestUpdateFeedbackRecordRequest_ChangedFields verifies presence-based change detection includes
// value_id when set and omits it when nil.
func TestUpdateFeedbackRecordRequest_ChangedFields(t *testing.T) {
	valueID := "opt_a"

	t.Run("value_id set is reported", func(t *testing.T) {
		got := (&UpdateFeedbackRecordRequest{ValueID: &valueID}).ChangedFields()
		if !slices.Contains(got, "value_id") {
			t.Fatalf("ChangedFields() = %v, want it to contain value_id", got)
		}
	})

	t.Run("value_id nil is omitted", func(t *testing.T) {
		text := "hi"

		got := (&UpdateFeedbackRecordRequest{ValueText: &text}).ChangedFields()
		if slices.Contains(got, "value_id") {
			t.Fatalf("ChangedFields() = %v, want it to omit value_id", got)
		}
	})
}

// TestUpdateFeedbackRecordRequest_FieldsChangedFrom verifies comparison-based change detection for
// value_id: a differing value is reported, an idempotent re-send of the same value is not.
func TestUpdateFeedbackRecordRequest_FieldsChangedFrom(t *testing.T) {
	oldID := "opt_a"
	newID := "opt_b"

	t.Run("changed value is reported", func(t *testing.T) {
		old := &FeedbackRecord{ValueID: &oldID}

		got := (&UpdateFeedbackRecordRequest{ValueID: &newID}).FieldsChangedFrom(old)
		if !slices.Contains(got, "value_id") {
			t.Fatalf("FieldsChangedFrom() = %v, want it to contain value_id", got)
		}
	})

	t.Run("unchanged value is not reported", func(t *testing.T) {
		old := &FeedbackRecord{ValueID: &oldID}
		sameID := "opt_a"

		got := (&UpdateFeedbackRecordRequest{ValueID: &sameID}).FieldsChangedFrom(old)
		if slices.Contains(got, "value_id") {
			t.Fatalf("FieldsChangedFrom() = %v, want it to omit value_id (idempotent re-send)", got)
		}
	})

	t.Run("newly set from nil is reported", func(t *testing.T) {
		old := &FeedbackRecord{}

		got := (&UpdateFeedbackRecordRequest{ValueID: &newID}).FieldsChangedFrom(old)
		if !slices.Contains(got, "value_id") {
			t.Fatalf("FieldsChangedFrom() = %v, want it to contain value_id", got)
		}
	})
}

package models

import (
	"testing"

	"github.com/formbricks/hub/internal/datatypes"
)

type openAPIRequestSchemas struct {
	Components struct {
		Schemas map[string]struct {
			Properties map[string]struct {
				MaxItems *int `yaml:"maxItems"`
				Items    struct {
					Enum []string `yaml:"enum"`
				} `yaml:"items"`
			} `yaml:"properties"`
		} `yaml:"schemas"`
	} `yaml:"components"`
}

// TestOpenAPIRequestArrayCapsMatchTheirValues pins each request array whose values come from a fixed
// set to a maxItems equal to that set's size. The server refuses a repeated or unknown value, so the
// set's size is the real bound; a spec that falls behind it (a seventh event type added, maxItems left
// at six) would make generated clients refuse a list the server accepts.
func TestOpenAPIRequestArrayCapsMatchTheirValues(t *testing.T) {
	t.Parallel()

	var spec openAPIRequestSchemas
	loadOpenAPISpec(t, &spec)

	retry := spec.Components.Schemas["EnrichmentRetryInputBody"].Properties["enrichments"]

	cases := map[string]struct {
		maxItems *int
		want     int
	}{
		"CreateWebhookInputBody.event_types": {
			spec.Components.Schemas["CreateWebhookInputBody"].Properties["event_types"].MaxItems,
			len(datatypes.GetAllEventTypes()),
		},
		"UpdateWebhookInputBody.event_types": {
			spec.Components.Schemas["UpdateWebhookInputBody"].Properties["event_types"].MaxItems,
			len(datatypes.GetAllEventTypes()),
		},
		"EnrichmentRetryInputBody.enrichments": {retry.MaxItems, len(retry.Items.Enum)},
	}

	for name, testCase := range cases {
		if testCase.maxItems == nil {
			t.Errorf("%s has no maxItems in openapi.yaml", name)

			continue
		}

		if testCase.want == 0 {
			t.Errorf("%s: found no allowed values to compare against; this check would assert nothing", name)

			continue
		}

		if *testCase.maxItems != testCase.want {
			t.Errorf("%s: maxItems is %d, but there are %d allowed values", name, *testCase.maxItems, testCase.want)
		}
	}
}

