package models

import (
	"errors"
	"reflect"
	"slices"
	"strconv"
	"strings"
	"testing"
	"time"
)

// TestParseEnumValues_Semantics locks the three behaviors the repeatable enum filters rely on:
// first-seen order is preserved, repeats collapse, and an empty value is a no-op rather than a
// rejected label. The last one is the reason these parse at decode time instead of via a `dive`
// validate tag — `?field_type=` has always meant "no field_type filter", and a dive tag would
// silently turn it into a 400.
func TestParseEnumValues_Semantics(t *testing.T) {
	t.Run("preserves first-seen order", func(t *testing.T) {
		got, err := ParseSentimentValues([]string{"positive", "very_negative", "neutral"})
		if err != nil {
			t.Fatalf("ParseSentimentValues() error = %v, want nil", err)
		}

		want := []SentimentValue{SentimentPositive, SentimentVeryNegative, SentimentNeutral}
		if !slices.Equal(got, want) {
			t.Fatalf("ParseSentimentValues() = %v, want %v", got, want)
		}
	})

	t.Run("deduplicates repeats", func(t *testing.T) {
		got, err := ParseEmotionValues([]string{"joy", "anger", "joy"})
		if err != nil {
			t.Fatalf("ParseEmotionValues() error = %v, want nil", err)
		}

		want := []EmotionValue{EmotionJoy, EmotionAnger}
		if !slices.Equal(got, want) {
			t.Fatalf("ParseEmotionValues() = %v, want %v (a repeated label must not grow the bound array)", got, want)
		}
	})

	t.Run("empty values yield no filter", func(t *testing.T) {
		got, err := ParseFieldTypes([]string{""})
		if err != nil {
			t.Fatalf("ParseFieldTypes() error = %v, want nil (?field_type= must stay a no-op filter)", err)
		}

		if got != nil {
			t.Fatalf("ParseFieldTypes() = %v, want nil", got)
		}
	})

	t.Run("no values yield no filter", func(t *testing.T) {
		got, err := ParseSentimentValues(nil)
		if err != nil || got != nil {
			t.Fatalf("ParseSentimentValues(nil) = %v, %v, want nil, nil", got, err)
		}
	})
}

// TestParseEnumValues_ReturnsTypedNil guards the decoder trap behind these helpers: the form
// decoder assigns a custom type func's result with reflect.Value.Set, and reflect.ValueOf(nil)
// yields the zero Value, which panics on Set. A bare `return nil, nil` in parseEnumValues would
// compile, pass every other test here, and then panic on the first `?sentiment=` request.
func TestParseEnumValues_ReturnsTypedNil(t *testing.T) {
	sentiments, err := ParseSentimentValues([]string{""})
	if err != nil {
		t.Fatalf("ParseSentimentValues() error = %v, want nil", err)
	}

	var boxed any = sentiments

	value := reflect.ValueOf(boxed)
	if !value.IsValid() {
		t.Fatal("reflect.ValueOf(result) is the zero Value; the decoder will panic on Set")
	}

	if value.Kind() != reflect.Slice {
		t.Fatalf("reflect.ValueOf(result).Kind() = %v, want %v", value.Kind(), reflect.Slice)
	}
}

// TestParseEnumValues_RejectsUnknown verifies each parser reports a typed error carrying the
// rejected value and unwrapping to its sentinel, which is what lets the query-decode layer name
// the offending parameter instead of falling back to a generic "is invalid".
func TestParseEnumValues_RejectsUnknown(t *testing.T) {
	tests := []struct {
		name     string
		parse    func([]string) error
		sentinel error
	}{
		{
			name: "sentiment",
			parse: func(v []string) error {
				_, err := ParseSentimentValues(v)

				return err
			},
			sentinel: ErrInvalidSentimentValue,
		},
		{
			name: "emotions",
			parse: func(v []string) error {
				_, err := ParseEmotionValues(v)

				return err
			},
			sentinel: ErrInvalidEmotionValue,
		},
		{
			name: "field_type",
			parse: func(v []string) error {
				_, err := ParseFieldTypes(v)

				return err
			},
			sentinel: ErrInvalidFieldType,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			err := tt.parse([]string{"hostile"})
			if err == nil {
				t.Fatal("parse() error = nil, want an invalid-value error")
			}

			if !errors.Is(err, tt.sentinel) {
				t.Fatalf("parse() error = %v, want it to unwrap to %v", err, tt.sentinel)
			}
		})
	}
}

// TestParseEnumValues_RejectsUnknownAmongValid verifies a bad label is rejected even when it
// arrives after good ones — the parser must not stop at the first success.
func TestParseEnumValues_RejectsUnknownAmongValid(t *testing.T) {
	if _, err := ParseSentimentValues([]string{"positive", "hostile"}); err == nil {
		t.Fatal("ParseSentimentValues() error = nil, want the trailing invalid label to be rejected")
	}
}

// TestValidEnumValuesStrings pins the human-readable label lists used in 400 reasons, including
// their order: sentiment reads in ordinal order with mixed last, emotions in canonical order.
func TestValidEnumValuesStrings(t *testing.T) {
	wantSentiment := "very_negative, negative, neutral, positive, very_positive, mixed"
	if got := ValidSentimentValuesString(); got != wantSentiment {
		t.Fatalf("ValidSentimentValuesString() = %q, want %q", got, wantSentiment)
	}

	wantEmotion := "joy, anger, sadness, fear, surprise, disgust"
	if got := ValidEmotionValuesString(); got != wantEmotion {
		t.Fatalf("ValidEmotionValuesString() = %q, want %q", got, wantEmotion)
	}
}

// TestFeedbackRecord_SortValue verifies the cursor bounds the column the listing is sorted by.
// If this drifts from the repository's resolveListOrdering, a next-page cursor carries a
// created_at value that the keyset predicate compares against collected_at (or vice versa), which
// silently skips and repeats rows instead of failing.
func TestFeedbackRecord_SortValue(t *testing.T) {
	collected := time.Date(2026, 1, 1, 0, 0, 0, 0, time.UTC)
	created := time.Date(2026, 6, 1, 0, 0, 0, 0, time.UTC)
	updated := time.Date(2026, 7, 1, 0, 0, 0, 0, time.UTC)
	record := &FeedbackRecord{CollectedAt: collected, CreatedAt: created, UpdatedAt: updated}

	tests := []struct {
		name  string
		field SortField
		want  time.Time
	}{
		{name: "collected_at", field: SortFieldCollectedAt, want: collected},
		{name: "created_at", field: SortFieldCreatedAt, want: created},
		{name: "updated_at", field: SortFieldUpdatedAt, want: updated},
		{name: "unknown falls back to the default sort", field: SortField("nonsense"), want: collected},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := record.SortValue(tt.field); !got.Equal(tt.want) {
				t.Fatalf("SortValue(%q) = %v, want %v", tt.field, got, tt.want)
			}
		})
	}
}

// TestDefaultSort pins the defaults to the ordering the endpoint had before sort was configurable.
// Changing either silently reorders every existing caller's first page.
func TestDefaultSort(t *testing.T) {
	if DefaultSortField != SortFieldCollectedAt || DefaultSortOrder != SortOrderDesc {
		t.Fatalf("defaults = (%q, %q), want (collected_at, desc)", DefaultSortField, DefaultSortOrder)
	}
}

// TestInvertedRanges_ReportsEachInvertedPair verifies every range pair is checked, and that the
// error is attributed to the lower bound so invalid_params names one correctable parameter.
func TestInvertedRanges_ReportsEachInvertedPair(t *testing.T) {
	filters := invertedFilters()

	got := make(map[string]string, len(filters.InvertedRanges()))
	for _, inverted := range filters.InvertedRanges() {
		got[inverted.MinParam] = inverted.MaxParam
	}

	want := map[string]string{
		"since":               "until",
		"created_since":       "created_until",
		"updated_since":       "updated_until",
		"value_date_min":      "value_date_max",
		"value_number_min":    "value_number_max",
		"sentiment_score_min": "sentiment_score_max",
	}

	if len(got) != len(want) {
		t.Fatalf("InvertedRanges() reported %v, want %v", got, want)
	}

	for minParam, maxParam := range want {
		if got[minParam] != maxParam {
			t.Fatalf("InvertedRanges() paired %q with %q, want %q", minParam, got[minParam], maxParam)
		}
	}
}

// TestInvertedRanges_CoversEveryRangeFilter is the guard that stops the next range filter from
// silently skipping validation. It reflects over the struct's form tags rather than restating the
// list, so adding a *_min or *_since parameter without wiring it into InvertedRanges fails here
// instead of shipping a filter that returns a confusing empty page when inverted.
func TestInvertedRanges_CoversEveryRangeFilter(t *testing.T) {
	checked := make(map[string]bool)
	for _, inverted := range invertedFilters().InvertedRanges() {
		checked[inverted.MinParam] = true
	}

	for field := range reflect.TypeFor[ListFeedbackRecordsFilters]().Fields() {
		tag, _, _ := strings.Cut(field.Tag.Get("form"), ",")

		// Lower bounds are spelled either `<thing>_min` or `[<thing>_]since`.
		if !strings.HasSuffix(tag, "_min") && !strings.HasSuffix(tag, "since") {
			continue
		}

		if !checked[tag] {
			t.Fatalf("filter %q is a range lower bound but InvertedRanges() does not check it", tag)
		}
	}
}

// TestInvertedRanges_IgnoresValidAndPartialRanges verifies a well-ordered range, an equal pair
// (inclusive bounds, so it selects exactly the boundary), and a half-open range all pass.
func TestInvertedRanges_IgnoresValidAndPartialRanges(t *testing.T) {
	early := time.Date(2026, 1, 1, 0, 0, 0, 0, time.UTC)
	late := time.Date(2026, 2, 1, 0, 0, 0, 0, time.UTC)
	low, high := -0.5, 0.5

	tests := []struct {
		name    string
		filters ListFeedbackRecordsFilters
	}{
		{name: "empty", filters: ListFeedbackRecordsFilters{}},
		{name: "ordered", filters: ListFeedbackRecordsFilters{Since: &early, Until: &late}},
		{name: "equal bounds", filters: ListFeedbackRecordsFilters{Since: &early, Until: &early}},
		{name: "lower bound only", filters: ListFeedbackRecordsFilters{SentimentScoreMin: &high}},
		{name: "upper bound only", filters: ListFeedbackRecordsFilters{SentimentScoreMax: &low}},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := tt.filters.InvertedRanges(); got != nil {
				t.Fatalf("InvertedRanges() = %v, want nil", got)
			}
		})
	}
}

// invertedFilters returns a filter set in which every range pair is supplied backwards.
func invertedFilters() *ListFeedbackRecordsFilters {
	early := time.Date(2026, 1, 1, 0, 0, 0, 0, time.UTC)
	late := time.Date(2026, 2, 1, 0, 0, 0, 0, time.UTC)
	low, high := -0.5, 0.5

	return &ListFeedbackRecordsFilters{
		Since: &late, Until: &early,
		CreatedSince: &late, CreatedUntil: &early,
		UpdatedSince: &late, UpdatedUntil: &early,
		ValueDateMin: &late, ValueDateMax: &early,
		ValueNumberMin: &high, ValueNumberMax: &low,
		SentimentScoreMin: &high, SentimentScoreMax: &low,
	}
}

// TestInvalidEnumValueErrors covers the message and nil-receiver behaviour of the two new error
// types, mirroring InvalidFieldTypeError. The message carries the rejected value for logs; the
// query-decode layer deliberately reports a canned reason instead, so the value never reaches the
// response body.
func TestInvalidEnumValueErrors(t *testing.T) {
	tests := []struct {
		name     string
		err      error
		nilErr   error
		wantIn   string
		sentinel error
	}{
		{
			name:     "sentiment",
			err:      &InvalidSentimentValueError{Value: "hostile"},
			nilErr:   (*InvalidSentimentValueError)(nil),
			wantIn:   "hostile",
			sentinel: ErrInvalidSentimentValue,
		},
		{
			name:     "emotion",
			err:      &InvalidEmotionValueError{Value: "ennui"},
			nilErr:   (*InvalidEmotionValueError)(nil),
			wantIn:   "ennui",
			sentinel: ErrInvalidEmotionValue,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if !strings.Contains(tt.err.Error(), tt.wantIn) {
				t.Fatalf("Error() = %q, want it to carry the rejected value %q", tt.err.Error(), tt.wantIn)
			}

			if !errors.Is(tt.err, tt.sentinel) {
				t.Fatalf("errors.Is(%v, %v) = false, want true", tt.err, tt.sentinel)
			}

			// A nil typed error must not panic — Error() is reached through fmt verbs in logs.
			if got := tt.nilErr.Error(); got != tt.sentinel.Error() {
				t.Fatalf("nil receiver Error() = %q, want %q", got, tt.sentinel.Error())
			}
		})
	}
}

// TestFilterValueCapsMatchTheirSets ties every repeatable filter's `max=` tag to the thing it is
// supposed to mirror, because a struct tag cannot reference a constant and so drifts silently.
//
// The enum caps are the failure that motivated this: adding a seventh emotion would leave
// `max=6` in place, and a request legitimately asking for all seven would start returning 400 with
// no test going red. The string caps just pin MaxFilterValues as the single documented number.
func TestFilterValueCapsMatchTheirSets(t *testing.T) {
	enumCaps := map[string]int{
		"field_type": len(ValidFieldTypeValues()),
		"sentiment":  len(SentimentValues()),
		"emotions":   len(EmotionValues()),
	}

	seen := map[string]bool{}

	for field := range reflect.TypeFor[ListFeedbackRecordsFilters]().Fields() {
		if field.Type.Kind() != reflect.Slice {
			continue
		}

		name, _, _ := strings.Cut(field.Tag.Get("form"), ",")

		sliceLevel, _, _ := strings.Cut(field.Tag.Get("validate"), ",dive")

		limit, ok := maxTagValue(t, sliceLevel)
		if !ok {
			t.Fatalf("repeatable filter %q has no max= cap; an unbounded IN-list is the one thing these tags exist to prevent", name)
		}

		seen[name] = true

		want := MaxFilterValues
		if enumCap, isEnum := enumCaps[name]; isEnum {
			want = enumCap
		}

		if limit != want {
			t.Fatalf("filter %q caps at %d, want %d", name, limit, want)
		}
	}

	for name := range enumCaps {
		if !seen[name] {
			t.Fatalf("enum filter %q is no longer a slice field; this test is checking nothing for it", name)
		}
	}
}

// maxTagValue returns the `max=N` from one half of a validate tag. Pass the portion before `,dive`
// for the slice-length cap, or the portion after it for the per-element cap.
func maxTagValue(t *testing.T, tagPart string) (int, bool) {
	t.Helper()

	for part := range strings.SplitSeq(tagPart, ",") {
		raw, found := strings.CutPrefix(part, "max=")
		if !found {
			continue
		}

		value, err := strconv.Atoi(raw)
		if err != nil {
			t.Fatalf("unparseable max tag %q", part)
		}

		return value, true
	}

	return 0, false
}

// TestStringFilterElementCapsMatchTheStoredWidth pins the per-element `max=` on every repeatable
// string filter to the width the column can actually hold.
//
// A filter value wider than the stored column can never match a row, so the cap costs nothing and
// turns a pointless query into a 400. The risk it guards is the reverse: a cap set *below* the
// stored width silently rejects a legitimate value. TestFilterValueCapsMatchTheirSets covers only
// the slice-length half of these tags, so without this the element half is unpinned.
//
// Two of these are not column widths. source_type and source_name are bare unbounded VARCHAR in
// migration 001, so 255 is an API-level cap chosen to match the sibling id columns rather than a
// mirror of the schema — for those two the "costs nothing" argument does not hold, and a value
// longer than 255 is storable but not filterable. Harmless for the short identifiers these
// actually carry, but it is a real (if theoretical) narrowing rather than a free assertion.
func TestStringFilterElementCapsMatchTheStoredWidth(t *testing.T) {
	// Column widths from the schema; language is VARCHAR(10), the rest VARCHAR(255) — except
	// source_type and source_name, which are unbounded VARCHAR and capped by API choice.
	const (
		idWidth       = 255
		languageWidth = 10
	)

	want := map[string]int{
		"submission_id": idWidth, "source_type": idWidth, "source_id": idWidth,
		"source_name": idWidth, "field_id": idWidth, "field_group_id": idWidth,
		"value_id": idWidth, "user_id": idWidth, "language": languageWidth,
	}

	seen := map[string]bool{}

	for field := range reflect.TypeFor[ListFeedbackRecordsFilters]().Fields() {
		name, _, _ := strings.Cut(field.Tag.Get("form"), ",")

		expected, tracked := want[name]
		if !tracked {
			continue
		}

		seen[name] = true

		_, elementPart, hasDive := strings.Cut(field.Tag.Get("validate"), ",dive,")
		if !hasDive {
			t.Fatalf("filter %q has no dive section, so its elements are unvalidated", name)
		}

		limit, ok := maxTagValue(t, elementPart)
		if !ok {
			t.Fatalf("filter %q does not cap element length; a value wider than the column can never match", name)
		}

		if limit != expected {
			t.Fatalf("filter %q caps elements at %d, want %d (the stored column width)", name, limit, expected)
		}
	}

	for name := range want {
		if !seen[name] {
			t.Fatalf("filter %q is no longer a field on the struct; this test is checking nothing for it", name)
		}
	}
}

package tests

import (
	"context"
	"fmt"
	"testing"
	"time"

	"github.com/google/uuid"
	"github.com/riverqueue/river"
	"github.com/riverqueue/river/riverdriver/riverpgxv5"
	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"

	"github.com/formbricks/hub/internal/config"
	"github.com/formbricks/hub/internal/huberrors"
	"github.com/formbricks/hub/internal/models"
	"github.com/formbricks/hub/internal/repository"
	"github.com/formbricks/hub/internal/service"
	"github.com/formbricks/hub/pkg/database"
)

// TestListPendingTaxonomyEmbeddingIDs exercises the real repair-selection query against River and
// enrichment failure state. Each exclusion is part of the safety contract: omitting one either
// duplicates provider work or permanently abandons recoverable records.
func TestListPendingTaxonomyEmbeddingIDs(t *testing.T) {
	ctx := context.Background()
	cfg, err := config.Load()
	require.NoError(t, err)

	db, err := database.NewPostgresPool(ctx, cfg.Database.URL, database.WithPoolConfig(cfg.Database.PoolConfig()))
	require.NoError(t, err)

	defer db.Close()

	embeddingsRepo := repository.NewEmbeddingsRepository(db)
	failuresRepo := repository.NewEnrichmentFailuresRepository(db)
	riverClient, err := river.NewClient(riverpgxv5.New(db), &river.Config{})
	require.NoError(t, err)

	tenantID := "embedding-reconcile-" + uuid.NewString()
	model := "taxonomy:reconcile-" + uuid.NewString()

	t.Cleanup(func() {
		_, _ = db.Exec(ctx, `DELETE FROM river_job WHERE args->>'feedback_record_id' IN (
			SELECT id::text FROM feedback_records WHERE tenant_id = $1
		)`, tenantID)
		_, _ = db.Exec(ctx, `DELETE FROM feedback_records WHERE tenant_id = $1`, tenantID)
	})

	seedValues := func(label, valueText, valueTextTranslated string) *models.FeedbackRecord {
		t.Helper()

		var record models.FeedbackRecord

		err := db.QueryRow(ctx, `
			INSERT INTO feedback_records (
				source_type, source_id, field_id, field_label, field_type,
				value_text, value_text_translated, tenant_id, submission_id, collected_at
			)
			VALUES ('formbricks', $1, 'feedback', 'Feedback', 'text'::field_type_enum,
			        $2, $3, $4, $5, '-infinity'::timestamptz)
			RETURNING id, tenant_id, updated_at`,
			"source-"+label, valueText, valueTextTranslated, tenantID, "submission-"+uuid.NewString(),
		).Scan(&record.ID, &record.TenantID, &record.UpdatedAt)
		require.NoError(t, err)

		return &record
	}
	seed := func(label string) *models.FeedbackRecord {
		t.Helper()

		return seedValues(label, "raw "+label, "translated "+label)
	}

	eligible := seed("eligible")
	embedded := seed("already-embedded")
	activeJob := seed("active-job")
	terminalCurrent := seed("terminal-current")
	terminalOldModel := seed("terminal-old-model")
	terminalOldRevision := seed("terminal-old-revision")
	transientFailure := seed("transient-failure")
	transientRetryable := seed("transient-retryable")

	whitespaceOnly := make([]*models.FeedbackRecord, 0, 7)
	for i, value := range []string{"\t", "\n", "\r\n", "\v", "\f", "\u00a0", "\u3000"} {
		whitespaceOnly = append(whitespaceOnly, seedValues(
			fmt.Sprintf("whitespace-%d", i), value, value,
		))
	}

	vector := make([]float32, models.EmbeddingVectorDimensions)
	vector[0] = 0.5
	require.NoError(t, embeddingsRepo.Upsert(ctx, embedded.ID, model, vector, nil))

	_, err = riverClient.Insert(ctx, service.FeedbackEmbeddingArgs{
		FeedbackRecordID: activeJob.ID,
		Model:            model,
		InputKind:        models.EmbeddingInputKindTaxonomyTranslated,
		ValueTextHash:    "live-event",
	}, &river.InsertOpts{Queue: service.EmbeddingsQueueName, MaxAttempts: 5})
	require.NoError(t, err)

	recordFailure := func(record *models.FeedbackRecord, contextKey string, terminal bool, reason string) {
		t.Helper()
		require.NoError(t, failuresRepo.RecordFailure(ctx, models.EnrichmentFailure{
			FeedbackRecordID: record.ID,
			TenantID:         tenantID,
			Enrichment:       models.EnrichmentNameTaxonomyEmbedding,
			Terminal:         terminal,
			Reason:           reason,
			Attempts:         5,
			ContextKey:       contextKey,
			SourceUpdatedAt:  &record.UpdatedAt,
		}))
	}

	recordFailure(terminalCurrent, model, true, string(huberrors.TerminalReasonContentFilter))
	recordFailure(terminalOldModel, "taxonomy:retired-model", true, string(huberrors.TerminalReasonContentFilter))
	recordFailure(terminalOldRevision, model, true, string(huberrors.TerminalReasonContentFilter))
	recordFailure(transientFailure, model, false, models.EnrichmentFailureReasonProviderError)
	recordFailure(transientRetryable, model, false, models.EnrichmentFailureReasonProviderError)
	_, err = db.Exec(ctx, `UPDATE feedback_record_enrichment_failures
		SET failed_at = NOW() - interval '1 hour'
		WHERE feedback_record_id = $1 AND enrichment = 'taxonomy_embedding'`, transientRetryable.ID)
	require.NoError(t, err)

	// Simulate an edit after the terminal failure. A marker tied to the old revision must not
	// suppress the new content, even though it was written for the same record and model.
	_, err = db.Exec(ctx, `UPDATE feedback_records SET updated_at = updated_at + interval '1 second' WHERE id = $1`,
		terminalOldRevision.ID)
	require.NoError(t, err)

	// This repository is shared by local integration runs, and a unique model makes every existing
	// fixture look missing. The fixture timestamps sort first so the assertion does not depend on a
	// database-wide inspection limit; bounded production top-up is asserted in the service unit test.
	ids, err := embeddingsRepo.ListPendingTaxonomyEmbeddingIDs(ctx, model, time.Now().Add(-15*time.Minute), 1_000)
	require.NoError(t, err)

	got := make(map[uuid.UUID]struct{}, len(ids))
	for _, id := range ids {
		got[id] = struct{}{}
	}

	for _, record := range []*models.FeedbackRecord{eligible, terminalOldModel, terminalOldRevision, transientRetryable} {
		assert.Contains(t, got, record.ID, "recoverable record %s must be selected", record.ID)
	}

	for _, record := range []*models.FeedbackRecord{embedded, activeJob, terminalCurrent, transientFailure} {
		assert.NotContains(t, got, record.ID, "already handled record %s must not be selected", record.ID)
	}

	for _, record := range whitespaceOnly {
		assert.NotContains(t, got, record.ID, "whitespace-only record %s must not be selected", record.ID)
	}
}

package tests

import (
	"context"
	"testing"

	"github.com/google/uuid"
	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"

	"github.com/formbricks/hub/internal/config"
	"github.com/formbricks/hub/internal/models"
	"github.com/formbricks/hub/internal/repository"
	"github.com/formbricks/hub/pkg/database"
)

// TestListPendingEnrichment pins what the reconciler will and will not pick up. Three of these
// four cases are the whole reason the query exists, and each would fail in a different, quiet way:
// a never-attempted record left out means the endpoint reports a remainder nothing drains, a
// retryable failure left out means an outage strands records permanently, and a terminal failure
// left IN means the sweep re-runs a content-filtered record forever at a provider call each tick.
func TestListPendingEnrichment(t *testing.T) {
	ctx := context.Background()
	cfg, err := config.Load()
	require.NoError(t, err)
	db, err := database.NewPostgresPool(ctx, cfg.Database.URL, database.WithPoolConfig(cfg.Database.PoolConfig()))
	require.NoError(t, err)

	defer db.Close()

	frepo := repository.NewFeedbackRecordsRepository(db)
	rrepo := repository.NewEnrichmentReconcileRepository(db)
	tenant := "pending-probe-" + uuid.NewString()

	pending := seedEnrichmentRecord(t, frepo, tenant, models.FieldTypeText, "needs sentiment")
	terminal := seedEnrichmentRecord(t, frepo, tenant, models.FieldTypeText, "refused forever")
	transient := seedEnrichmentRecord(t, frepo, tenant, models.FieldTypeText, "failed but retryable")
	writeFailed := seedEnrichmentRecord(t, frepo, tenant, models.FieldTypeText, "classified but never written")
	doneRec := seedEnrichmentRecord(t, frepo, tenant, models.FieldTypeText, "already enriched")

	_, err = db.Exec(ctx, `INSERT INTO feedback_record_enrichment_failures
		(feedback_record_id, enrichment, tenant_id, terminal, reason) VALUES ($1,'sentiment',$2,true,'content_filter')`,
		terminal.ID, tenant)
	require.NoError(t, err)
	_, err = db.Exec(ctx, `INSERT INTO feedback_record_enrichment_failures
		(feedback_record_id, enrichment, tenant_id, terminal, reason) VALUES ($1,'sentiment',$2,false,'provider_error')`,
		transient.ID, tenant)
	require.NoError(t, err)

	// The second non-terminal reason. It is not a provider failure at all — the model answered and
	// the write is what died — but it leaves the record just as un-enriched, so the sweep owes it
	// the same retry. Pinned separately because the exclusion here keys on `terminal`, and a later
	// change that keyed on the reason instead would quietly strand every write failure.
	_, err = db.Exec(ctx, `INSERT INTO feedback_record_enrichment_failures
		(feedback_record_id, enrichment, tenant_id, terminal, reason) VALUES ($1,'sentiment',$2,false,'write_failed')`,
		writeFailed.ID, tenant)
	require.NoError(t, err)

	label, score := models.SentimentPositive, 1.0
	require.NoError(t, frepo.SetSentiment(ctx, doneRec.ID, &label, &score, nil))

	got, err := rrepo.ListPendingEnrichment(ctx, models.EnrichmentNameSentiment, "", pendingPageLimit)
	require.NoError(t, err)
	require.Less(t, len(got), pendingPageLimit,
		"the shared test database now fills this page, so the seeded records may be truncated off "+
			"the end — raise pendingPageLimit rather than trusting the assertions below")

	ids := map[uuid.UUID]bool{}

	for _, target := range got {
		if target.TenantID == tenant {
			ids[target.ID] = true
		}
	}

	assert.True(t, ids[pending.ID], "never-attempted record must be pending")

	// A record whose enrichment already has a job in flight — on ANY queue — is not pending: it is
	// scheduled. This exclusion, not River uniqueness, is what stops the sweep double-enqueueing
	// work the event path or a backfill command is already handling (their jobs carry no matching
	// unique key), and it is what keeps an in-backoff head from starving the tail.
	inflight := seedEnrichmentRecord(t, frepo, tenant, models.FieldTypeText, "already queued elsewhere")
	_, err = db.Exec(ctx, `
		INSERT INTO river_job (state, queue, kind, priority, args, max_attempts)
		VALUES ('retryable', 'sentiments', 'feedback_sentiment', 1,
			jsonb_build_object('feedback_record_id', $1::text, 'value_text_hash', 'abc'), 3)`, inflight.ID)
	require.NoError(t, err)

	// And one whose job FINISHED (completed): finished jobs are not in flight, so if the record is
	// somehow still un-enriched it must be pending again — the exclusion must not overreach.
	finished := seedEnrichmentRecord(t, frepo, tenant, models.FieldTypeText, "job completed but record untouched")
	_, err = db.Exec(ctx, `
		INSERT INTO river_job (state, queue, kind, priority, args, max_attempts, finalized_at)
		VALUES ('completed', 'sentiments', 'feedback_sentiment', 1,
			jsonb_build_object('feedback_record_id', $1::text, 'value_text_hash', 'abc'), 3, NOW())`, finished.ID)
	require.NoError(t, err)

	got2, err := rrepo.ListPendingEnrichment(ctx, models.EnrichmentNameSentiment, "", pendingPageLimit)
	require.NoError(t, err)
	require.Less(t, len(got2), pendingPageLimit,
		"the shared test database now fills this page, so the seeded records may be truncated off "+
			"the end — raise pendingPageLimit rather than trusting the assertions below")

	ids2 := map[uuid.UUID]bool{}

	for _, target := range got2 {
		if target.TenantID == tenant {
			ids2[target.ID] = true
		}
	}

	assert.False(t, ids2[inflight.ID], "a record with an in-flight job must not be re-enqueued")
	assert.True(t, ids2[finished.ID], "a finished job is not in flight; the record is pending again")
	assert.True(t, ids[transient.ID], "a retryable provider failure must come back as pending")
	assert.True(t, ids[writeFailed.ID], "a failed write is retryable too, and must come back as pending")
	assert.False(t, ids[terminal.ID], "a terminal failure must be excluded or the sweep never ends")
	assert.False(t, ids[doneRec.ID], "an enriched record must not be pending")
	assert.Len(t, ids, 3, "exactly the three pending records, no more")

	// The reconciler is cross-tenant on purpose — a provider outage is deployment-wide — so it
	// must return other tenants' work too. Only the per-tenant filter above hides it here.
	assert.NotEmpty(t, got, "the sweep is global, not tenant-scoped")
}

// TestQueueDepthCountsRetryableJobs binds the state set the depth control uses to the one the
// pending set uses. They have to be the same set, and the reason is not obvious from either alone.
//
// A record whose job is retryable is excluded from the pending set — correctly, it is already
// being handled. If that same job is also invisible to the depth count, the sweep sees an empty
// queue and tops it up to TargetDepth with DIFFERENT records, on top of the ones backing off.
// Whenever the retry window exceeds the sweep interval — reachable by raising *_MAX_ATTEMPTS,
// since River backs off by roughly attempt^4 seconds — that repeats every tick and the queue grows
// without limit, which is exactly the unbounded river_job growth TargetDepth exists to prevent.
//
// Scheduled is pinned alongside it because River moves a job retryable -> scheduled as its backoff
// elapses, so a set that counted only one of the two would leave the same hole open for part of
// every retry cycle.
func TestQueueDepthCountsRetryableJobs(t *testing.T) {
	ctx := context.Background()
	db := newPurgeTestDB(ctx, t)
	rrepo := repository.NewEnrichmentReconcileRepository(db)

	queue := "depth-probe-" + uuid.NewString()

	insert := func(state string, finalized bool) {
		if finalized {
			_, err := db.Exec(ctx, `INSERT INTO river_job (state, queue, kind, priority, args, max_attempts, finalized_at)
				VALUES ($1, $2, 'feedback_sentiment', 1, '{}'::jsonb, 3, NOW())`, state, queue)
			require.NoError(t, err)

			return
		}

		_, err := db.Exec(ctx, `INSERT INTO river_job (state, queue, kind, priority, args, max_attempts)
			VALUES ($1, $2, 'feedback_sentiment', 1, '{}'::jsonb, 3)`, state, queue)
		require.NoError(t, err)
	}

	for _, state := range []string{"available", "pending", "retryable", "running", "scheduled"} {
		insert(state, false)
	}

	// Finished work must NOT count: it occupies no capacity, and counting it would wedge the queue
	// at its target forever once TargetDepth jobs had ever completed on it.
	insert("completed", true)
	insert("cancelled", true)

	depths, err := rrepo.CountInFlightByQueue(ctx, []string{queue})
	require.NoError(t, err)

	assert.Equal(t, int64(5), depths[queue],
		"every in-flight state occupies the lane, retryable included — otherwise the sweep tops up "+
			"on top of work that is already backing off and TargetDepth bounds nothing")
}
